{
  "title": "functions.expression.VideoInputSchema",
  "description": "Schema for a video input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected video.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.VideoInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ArrayInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected image.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    }
  }
}
